SELECT SIGNGU_NAME 
FROM ldong_signgu_code 
WHERE LDONGREGNCD = #{lDongRegnCd} AND LDONGSIGNGUCD = #{lDongSignguCd}

mapper.update:
UPDATE destination
SET view_count = view_count + 1
WHERE contentid = #{contentid}

mapper.select:
SELECT contentid, contenttypeid, title, tel, addr1, addr2, lDongRegnCd, lDongSignguCd, mapx, mapy, firstimage, firstimage2, view_count AS viewCount FROM destination
AND contenttypeid = #{contenttypeid}
ORDER BY modifiedtime DESC

SELECT COUNT(*) FROM destination


        AND contenttypeid = #{contenttypeid}


        AND contenttypeid NOT IN ('15', '25')

SELECT contentid, contenttypeid, title, tel, addr1, addr2, lDongRegnCd, lDongSignguCd, mapx, mapy, firstimage, firstimage2, view_count AS viewCount FROM destination WHERE lDongRegnCd = #{lDongRegnCd}
AND INSTR(',' || #{lDongSignguCd} || ',', ',' || lDongSignguCd || ',') > 0
ORDER BY modifiedtime DESC

SELECT * FROM ( SELECT d.*, ROWNUM AS rn FROM ( SELECT contentid, contenttypeid, title, overview, homepage, tel, addr1, addr2, zipcode, lDongRegnCd, lDongSignguCd, mapx, mapy, mlevel, firstimage, firstimage2, modifiedtime, view_count AS viewCount, sync_date AS syncDate, created_at AS createdAt FROM destination
AND contenttypeid = #{contenttypeid}
AND contenttypeid NOT IN ('15', '25')
ORDER BY view_count DESC, contentid DESC
ORDER BY modifiedtime DESC, contentid DESC
) d WHERE ROWNUM <= #{offset} + #{limit} ) WHERE rn > #{offset}

SELECT * FROM ( SELECT d.*, ROWNUM AS rn FROM ( SELECT contentid, contenttypeid, title, overview, homepage, tel, addr1, addr2, zipcode, lDongRegnCd, lDongSignguCd, mapx, mapy, mlevel, firstimage, firstimage2, modifiedtime, view_count AS viewCount, sync_date AS syncDate, created_at AS createdAt FROM destination WHERE lDongRegnCd = #{lDongRegnCd}
AND contenttypeid = #{contenttypeid}
AND contenttypeid NOT IN ('15', '25')
AND INSTR(',' || #{lDongSignguCd} || ',', ',' || lDongSignguCd || ',') > 0
ORDER BY view_count DESC, contentid DESC
ORDER BY modifiedtime DESC, contentid DESC
) d WHERE ROWNUM <= #{offset} + #{limit} ) WHERE rn > #{offset}

SELECT COUNT(*) FROM destination
WHERE lDongRegnCd = #{lDongRegnCd}

    AND contenttypeid = #{contenttypeid}


    AND contenttypeid NOT IN ('15', '25')


    AND INSTR(',' || #{lDongSignguCd} || ',', ',' || lDongSignguCd || ',') > 0

SELECT * FROM ( SELECT d.*, ROWNUM AS rn FROM ( SELECT contentid, contenttypeid, title, overview, homepage, tel, addr1, addr2, zipcode, lDongRegnCd, lDongSignguCd, mapx, mapy, mlevel, firstimage, firstimage2, modifiedtime, view_count AS viewCount, sync_date AS syncDate, created_at AS createdAt FROM destination WHERE (title LIKE '%' || #{keyword} || '%' OR addr1 LIKE '%' || #{keyword} || '%') AND lDongRegnCd = #{lDongRegnCd}
AND INSTR(',' || #{lDongSignguCd} || ',', ',' || lDongSignguCd || ',') > 0
ORDER BY view_count DESC, title ASC ) d WHERE ROWNUM <= #{offset} + #{limit} ) WHERE rn > #{offset}

SELECT * FROM (
    SELECT 
        d.*,
        ROWNUM AS rn
    FROM (
        SELECT * FROM destination ORDER BY contentid
    ) d
    WHERE ROWNUM <= #{endIndex}
)
WHERE rn >= #{startIndex}
